// Generates db/05_samples.sql from samples/samples.js
const fs = require('fs'), path = require('path');
const S = require('../samples/samples.js');
const E = require('../static/rpt-engine.js');
const q = (s) => { if (s.includes("~'")) throw new Error('quote clash'); return "q'~" + s + "~'"; };
const chunks = (s, n) => { const out = []; for (let i = 0; i < s.length; i += n) out.push(s.slice(i, i + n)); return out; };
let sql = `--------------------------------------------------------------------------------
-- Report Studio - sample content (generated by tools/build-samples-sql.js)
-- Creates image LOGO and reports ${S.reports.map(r => r.report.code).join(', ')} (replaced if they exist)
--------------------------------------------------------------------------------
set define off

declare
  l_svg varchar2(4000) := ${q(S.logoSvg)};
begin
  delete from rpt_assets where code = 'LOGO';
  insert into rpt_assets (code, file_name, mime_type, content)
  values ('LOGO', 'logo.svg', 'image/svg+xml', to_blob(utl_raw.cast_to_raw(l_svg)));
  commit;
end;
/
`;
for (const r of S.reports) {
  const layout = JSON.stringify(E.normalizeLayout(JSON.parse(JSON.stringify(r.layout))));
  sql += `
-- ${r.report.code}: ${r.report.description}
declare
  l_layout clob;
  l_id     number;
begin
  delete from rpt_reports where code = '${r.report.code}';
  dbms_lob.createtemporary(l_layout, true);
${chunks(layout, 600).map(c => `  dbms_lob.append(l_layout, ${q(c)});`).join('\n')}
  insert into rpt_reports (code, name, description, layout, status, version_no)
  values ('${r.report.code}', ${q(r.report.name)}, ${q(r.report.description)}, l_layout, '${r.report.status}', 1)
  returning report_id into l_id;
${r.sources.map((s, i) => `  insert into rpt_sources (report_id, name, sql_text, test_params, seq)
  values (l_id, '${s.name}', ${q(s.sql)}, ${q(JSON.stringify(s.params || {}))}, ${(i + 1) * 10});`).join('\n')}
  insert into rpt_versions (report_id, version_no, layout, sources)
  values (l_id, 1, l_layout, ${q(JSON.stringify(r.sources.map(s => ({ name: s.name, sql: s.sql, params: s.params || {} }))))});
  commit;
end;
/
`;
}
fs.writeFileSync(path.join(__dirname, '..', 'db', '05_samples.sql'), sql);
console.log('db/05_samples.sql', sql.length, 'chars; longest line', Math.max(...sql.split('\n').map(l => Buffer.byteLength(l))), 'bytes');
